"use client";
import Script from 'next/script';
import { useEffect, useRef, useState } from 'react';
type Stats = {width:number; height:number; videoRenderFramerate:number; videoFrameDropCount:number; videoFrameDecodeCount:bigint; videoBitrate:number};
type Player = {load:(url:string,options:object)=>Promise<void>; play:(options:object)=>Promise<void>; destroy:()=>Promise<void>; on:(event:string,cb:(...args:unknown[])=>void)=>void; getStats:()=>Stats};
declare global {interface Window { AVPlayer: new (options:object)=>Player }}
export default function Home() {
  const container=useRef<HTMLDivElement>(null);
  const player=useRef<Player|null>(null);
  const [ready,setReady]=useState(false), [camera,setCamera]=useState(false);
  const [source,setSource]=useState('camera'), [mode,setMode]=useState('software');
  const [status,setStatus]=useState('Ready'), [error,setError]=useState('');
  const [active,setActive]=useState(false), [busy,setBusy]=useState(false);
  const [stats,setStats]=useState({fps:0,width:0,height:0,dropped:0,frames:0,bitrate:0});
  const [isolated,setIsolated]=useState(false);
  const [configured,setConfigured]=useState(false);
  useEffect(()=> {setIsolated(crossOriginIsolated); fetch('/api/status', {cache:'no-store'}).then(r=>{if(!r.ok) throw new Error('Configuration unavailable');return r.json();}).then(d=>{setCamera(d.cameraConfigured);setSource(d.defaultSource);setConfigured(true);}).catch(()=>setError('Server status unavailable.')); return ()=>{void player.current?.destroy();};},[]);
  useEffect(()=>{const timer=setInterval(()=>{
    if (!player.current) return;
    try {const s=player.current.getStats(); setStats({fps:s.videoRenderFramerate||0,width:s.width||0,height:s.height||0,dropped:s.videoFrameDropCount||0,frames:Number(s.videoFrameDecodeCount||0),bitrate:s.videoBitrate||0});} catch {}
  },1000); return ()=>clearInterval(timer);},[]);
  async function stop() {setBusy(true); const old=player.current; player.current=null; try {await old?.destroy();} finally {setActive(false);setBusy(false);setStatus('Stopped');}}
  async function start() {
    if (!ready || !configured || !container.current || busy) return;
    setBusy(true);setError('');setStatus('Connecting');setStats({fps:0,width:0,height:0,dropped:0,frames:0,bitrate:0});
    try {
      if (player.current) await player.current.destroy();
      const p=new window.AVPlayer({container:container.current,
        enableWebCodecs:mode==='auto',enableHardware:mode==='auto',checkUseMSE:()=>false,
        enableWorker:true, enableWebGPU:false,lowLatency:true,enableJitterBuffer:true,jitterBufferMin:0.2,jitterBufferMax:1,
        getWasm:(type:string,codec:number)=>{if(type==='decoder' && codec===173) return '/wasm/hevc-simd.wasm'; throw new Error('This prototype supports H.265 video only.');}
      });
      player.current=p;
      p.on('firstVideoRendered',()=>setStatus('Playing'));
      p.on('error',()=>{setError('Playback failed. Check the stream and server configuration, then reconnect.');setStatus('Error');});
      p.on('ended',()=>setStatus('Stream ended'));
      p.on('timeout',()=>{setStatus('Timed out');setError('Stream timed out. Reconnect to try again.');});
      await p.load(location.origin+'/api/stream?source='+source,{isLive:true,ext:'ts',maxProbeDuration:2});
      await p.play({audio:false,video:true}); setActive(true);
    } catch(e) {setError(e instanceof Error?e.message:'Unable to play stream.');setStatus('Error');await player.current?.destroy();player.current=null;setActive(false);}
    finally {setBusy(false);}
  }
  return <main>
    <Script src="/vendor/avplayer.js" strategy="afterInteractive" onReady={()=>setReady(true)} onError={()=>setError('Player assets missing. Run npm run setup.')}/>
    <header><a className="brand" href="/">▧ <span>HEVC<span className="light"> Studio</span></span></a><span className="badge">CAMERA DEFAULT · v1.0.2</span></header>
    <section className="intro"><span className="eyebrow">H.265 / NO INSTALLATION</span><h1>Your stream.<br/><span>Now in the browser.</span></h1><p>A dedicated workspace to test live HEVC playback with a software decoder running on your device.</p></section>
    <div className="workspace"><section className="viewer"><div className="viewerbar"><span><i className={status==='Playing'?'dot live':'dot'}/>{source==='demo'?'HEVC test pattern':'Camera 01'}</span><span>{status}</span></div>
      <div className="screen"><div className="canvas" ref={container}/>{!active&&!busy&&<div className="empty"><div className="playicon">▷</div><h2>Ready when you are</h2><p>Select a source and start the stream.</p><small>Real H.265 decoding · Video only</small></div>}</div>
      <div className="metrics">{[['Render FPS',stats.fps||'—'],['Resolution',stats.width?stats.width+' × '+stats.height:'—'],['Decoded frames',stats.frames],['Dropped frames',stats.dropped]].map(([label,value])=><div key={label}><strong>{value}</strong><span>{label}</span></div>)}</div>
    </section><aside><span className="eyebrow">STREAM CONTROLS</span><h2>Make the connection</h2>
      <label htmlFor="source">Video source</label><select id="source" value={source} disabled={active||busy} onChange={e=>setSource(e.target.value)}><option value="demo">Built-in H.265 demo</option><option value="camera" disabled={!camera}>RTSP camera {camera?'':'· not configured'}</option></select>
      <p className="hint">{source==='demo'?'A looping 720p HEVC test stream served from this application.':'Camera credentials stay on the server.'}</p>
      <label htmlFor="decoder">Decoder preference</label><select id="decoder" value={mode} disabled={active||busy} onChange={e=>setMode(e.target.value)}><option value="software">Software · WebAssembly</option><option value="auto">Prefer native · WASM fallback</option></select>
      <p className="hint">Software mode works without native HEVC support. Native preference does not guarantee hardware acceleration.</p>
      <button className="primary" disabled={!ready||!configured||busy||active} onClick={start}>{busy?'Connecting…':'▶ Start stream'}</button><button disabled={!active||busy} onClick={stop}>Stop stream</button>
      {error&&<p role="alert" className="error">{error}</p>}
      <div className="environment"><span className="dot live"/> {isolated?'Isolated context · workers available':'Single-context fallback'}<br/><span className="transport">MPEG-TS / HTTP · No server transcoding</span></div>
    </aside></div>
    <section className="notes"><div><b>01 / Verify playback</b><p>Start with the included test stream. Watch decoded frames increase to confirm the decoder is working.</p></div><div><b>02 / Connect your camera</b><p>Set CAMERA_RTSP_URL in the server environment and restart. Then select RTSP camera.</p></div><div><b>03 / Measure before scaling</b><p>Try a camera substream first. Resolution, frame rate and device CPU determine software decoding performance.</p></div></section>
    <footer>HEVC Studio <span>Single-camera prototype · Browser-only viewing</span></footer>
  </main>;
}
